 // 履带板的金属件与橡胶垫共用一个材质，靠贴图分区区分颜色、金属度与粗糙度，使每块履带板合并为一个网格并进入同侧骨骼合批。
 const wheels=SPEC.wheels.map(w=>({...w,g:get(w.g),center:new T.Vector3(...w.center)})),hatches=SPEC.hatches.map(get),ramp=get(SPEC.ramp),turretParts=SPEC.turretParts.map(get),cap=get(SPEC.cap);
