   const old=o.geometry,g=old.clone();g.type=old.type;if(old.parameters)g.parameters=old.parameters;o.geometry=g;const uv=g.attributes.uv;
   for(let i=0;i<uv.count;i++)uv.setXY(i,k==='rubber'?.75:.25+uv.getX(i),.5+uv.getY(i));uv.needsUpdate=true;
   o.userData.materialKey='dark';m.color.setHex(0xffffff);m.map=trackMap;m.metalness=1;m.metalnessMap=trackSurface;m.roughness=1;m.roughnessMap=trackSurface;m.bumpMap=null;m.envMapIntensity=1;
